import pandas as pd
from typing import Optional

def run(inputs: dict[str, pd.DataFrame]) -> dict[str, pd.DataFrame]:
    target_state = inputs["target_state"].copy()
    cdc_events = inputs["cdc_events"].copy()

    # Ensure proper types
    target_state["order_id"] = target_state["order_id"].astype("int64")
    target_state["status"] = target_state["status"].astype("str")
    target_state["amount"] = target_state["amount"].astype("float64")
    target_state["last_seq"] = target_state["last_seq"].astype("int64")

    cdc_events["seq"] = cdc_events["seq"].astype("int64")
    cdc_events["order_id"] = cdc_events["order_id"].astype("int64")
    cdc_events["op"] = cdc_events["op"].astype("str")
    cdc_events["status"] = cdc_events["status"].astype("str")
    cdc_events["amount"] = cdc_events["amount"].astype("float64")

    # Step 1: Remove duplicate events (same seq)
    cdc_events = cdc_events.drop_duplicates(subset=["seq"], keep="first")

    # Step 2: Sort by seq to process in order
    cdc_events = cdc_events.sort_values("seq").reset_index(drop=True)

    # Initialize new_state as a copy of target_state
    new_state = target_state.copy()
    new_state_dict = {}
    for _, row in new_state.iterrows():
        new_state_dict[row["order_id"]] = {
            "status": row["status"],
            "amount": row["amount"],
            "last_seq": row["last_seq"]
        }

    # Track which orders had rows and their last applied operation
    order_last_op = {}  # order_id -> (op, seq)
    orders_ever_existed = set(target_state["order_id"].values)

    # Step 3: Process events in seq order
    for _, event in cdc_events.iterrows():
        order_id = event["order_id"]
        seq = event["seq"]
        op = event["op"]
        status = event["status"]
        amount = event["amount"]

        # Replay guard: skip if order exists in target_state and seq <= last_seq
        if order_id in new_state_dict:
            if seq <= new_state_dict[order_id]["last_seq"]:
                continue

        # Apply the event
        if op in ("I", "U"):
            if order_id not in orders_ever_existed:
                orders_ever_existed.add(order_id)

            if order_id in new_state_dict:
                # Update existing row
                new_state_dict[order_id]["status"] = status
                # For 'U', NULL amount means keep existing; for 'I', use new amount
                if op == "I" or pd.notna(amount):
                    new_state_dict[order_id]["amount"] = amount
                new_state_dict[order_id]["last_seq"] = seq
            else:
                # Create new row
                new_state_dict[order_id] = {
                    "status": status,
                    "amount": amount,
                    "last_seq": seq
                }

            order_last_op[order_id] = (op, seq)

        elif op == "D":
            if order_id in new_state_dict:
                del new_state_dict[order_id]
            if order_id not in orders_ever_existed:
                orders_ever_existed.add(order_id)
            order_last_op[order_id] = (op, seq)

    # Step 4: Build new_state output
    result_rows = []
    for order_id, data in new_state_dict.items():
        result_rows.append({
            "order_id": order_id,
            "status": data["status"],
            "amount": data["amount"],
            "last_seq": data["last_seq"]
        })

    if result_rows:
        new_state_output = pd.DataFrame(result_rows)
    else:
        new_state_output = pd.DataFrame(columns=["order_id", "status", "amount", "last_seq"])

    new_state_output = new_state_output.astype({
        "order_id": "int64",
        "status": "str",
        "amount": "float64",
        "last_seq": "int64"
    })

    # Step 5: Build tombstones output
    tombstone_rows = []
    for order_id in orders_ever_existed:
        if order_id in order_last_op:
            last_op, last_seq = order_last_op[order_id]
            if last_op == "D":
                tombstone_rows.append({
                    "order_id": order_id,
                    "deleted_seq": last_seq
                })

    if tombstone_rows:
        tombstones = pd.DataFrame(tombstone_rows)
    else:
        tombstones = pd.DataFrame(columns=["order_id", "deleted_seq"])

    tombstones = tombstones.astype({
        "order_id": "int64",
        "deleted_seq": "int64"
    })

    return {
        "new_state": new_state_output,
        "tombstones": tombstones
    }
